import { mkdir, writeFile } from 'node:fs/promises';
import { createServer } from 'vite';
import { fileURLToPath } from 'node:url';
import { homedir } from 'node:os';
import { join } from 'node:path';

const output = new URL('../dev-data/usage-acceptance/', import.meta.url);
await mkdir(output, { recursive: true });
await writeFile(new URL('index.html', output), `<!doctype html>
<!-- Generated by scripts/usage-ui.mjs; do not edit. -->
<html lang="zh-CN"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Codex 用量交互验收</title></head><body><div id="app"></div><script type="module">
window.isTauri = true;
window.__TAURI_INTERNALS__ = {
  metadata: { currentWindow: { label: 'main' }, currentWebview: { label: 'main', windowLabel: 'main' } },
  transformCallback: () => 1, unregisterCallback: () => {},
  invoke: async (command, args = {}) => {
    if (command.startsWith('usage_')) {
      const response = await fetch('http://127.0.0.1:5199/invoke/' + command, { method: 'POST', body: JSON.stringify(args) });
      const result = await response.json();
      if (result.error) throw result.error;
      return result.data;
    }
    if (command.startsWith('plugin:event|')) return 1;
    if (command === 'plugin:dialog|save') return ${JSON.stringify(fileURLToPath(new URL('export.csv', output)))};
    if (command === 'workspace_open' || command === 'workspace_refresh') return { root: '/usage-acceptance', repositories: [], warnings: [] };
    if (command === 'theme_get') return { preset: 'ChatGPT', accent: '#3566F0', background: '#FFFFFF', foreground: '#1A1C1F', font: 'system' };
    if (command === 'theme_save') return args.theme;
    if (command === 'plugin:autostart|is_enabled') return false;
    if (command === 'settings_get') return { chat: { baseUrl: '', model: '', hasApiKey: false }, embedding: { baseUrl: '', model: '', hasApiKey: false }, codexDirectory: ${JSON.stringify(process.env.CODEX_HOME || join(homedir(), '.codex'))}, archiveEnabled: false, archiveStartedAt: null, runInBackground: false };
    if (command === 'archive_status') return { enabled: false, startedAt: null, scanning: false, processedTurns: 0, writtenMemories: 0, memoryWrites: 0, pendingEmbeddings: 0, failedEmbeddings: 0, failedEmbeddingDetails: [], processingEmbeddings: 0, recentTurns: [], chatInputTokens: 0, chatOutputTokens: 0, embeddingInputTokens: 0, usageIncomplete: false, lastError: null };
    if (command === 'memory_search') return [];
    if (command === 'memory_graph') return { nodes: [], edges: [] };
    if (command === 'plugin:opener|open_url') return null;
    throw new Error('Unexpected acceptance command: ' + command);
  },
};
await import('/src/main.ts');
</script></body></html>`);
if (!process.argv.includes('--generate-only')) {
  const server = await createServer({ server: { host: '127.0.0.1', port: 5180, strictPort: true } });
  await server.listen();
  console.log('Usage acceptance: http://127.0.0.1:5180/dev-data/usage-acceptance/index.html');
}
